-- ============================================================================
-- Fiches d'évaluation, bloc 3 : chargement de la bibliothèque Digital Football
-- Source : docs/fiches-evaluation/bloc0-bibliotheque-et-droits.md (validé le 2026-11-19)
-- 172 lignes : 156 critères notés (131 par tranche d'âge + 25 par poste), 12 tests, 4 oui / non.
--
-- Ce fichier ne touche QUE la table bibliotheque_criteres (créée au bloc 1).
-- Il peut être relancé sans danger : un critère déjà présent est mis à jour, pas doublé.
-- Aucun objectif chiffré : le club le fixe dans son modèle.
-- À exécuter dans l'éditeur SQL de Supabase, après sauvegarde.
-- ============================================================================

begin;

on conflict (code) do update set
  type = excluded.type, tranche = excluded.tranche, poste = excluded.poste, pilier = excluded.pilier,
  libelle = excluded.libelle, acquis_quand = excluded.acquis_quand, unite = excluded.unite, sens = excluded.sens,
  a_partir_de = excluded.a_partir_de, remarque = excluded.remarque, ordre = excluded.ordre;

commit;
